mapper.select:
SELECT payout_id FROM payout
WHERE processor             IS NOT DISTINCT FROM #{processor}
  AND payment_type          IS NOT DISTINCT FROM #{paymentType}
  AND calculation_basis     IS NOT DISTINCT FROM #{calculationBasis}
  AND calculated_amount     IS NOT DISTINCT FROM #{calculatedAmount}
  AND deduction_item        IS NOT DISTINCT FROM #{deductionItem}
  AND final_payment_amount  IS NOT DISTINCT FROM #{finalPaymentAmount}
ORDER BY payout_id DESC
LIMIT 1
